# ============================================================
# 3. 키워드 매칭 함수
# ============================================================
def _match_keywords(query, keywords):
    """
    키워드 리스트 중 하나라도 질문에 포함되면 True.
    정규식 패턴(r"..." 형태)도 지원.
    """
    query_lower = query.lower()
    for kw in keywords:
        # 정규식 패턴인 경우
        if kw.startswith(r"\b") or kw.startswith(r"\d") or kw.startswith("#") or kw.startswith(r"i\d") or kw.startswith(r"#"):
            try:
                if re.search(kw, query_lower):
                    return True
            except re.error:
                # 정규식이 아닌 경우 단순 문자열 매칭
                if kw.lower() in query_lower:
                    return True
        else:
            if kw.lower() in query_lower:
                return True
    return False




def _match_keywords_all(query, keywords):
    """
    리스트의 키워드가 모두(전부) 질문에 포함되어야 True.
    정규식 패턴(r"..." 형태)도 지원.
    """
    query_lower = query.lower()
    for kw in keywords:
        if kw.startswith(r"\b") or kw.startswith(r"\d") or kw.startswith("#") or kw.startswith(r"i\d"):
            try:
                if not re.search(kw, query_lower):
                    return False
            except re.error:
                if kw.lower() not in query_lower:
                    return False
        else:
            if kw.lower() not in query_lower:
                return False
    return True


def _match_periodontal(query, set1_keywords, independent_keywords):
    """
    세트1 2개 이상 OR (세트1 1개 + 독립키워드 1개) 이면 True
    """
    query_lower = query.lower()
    set1_count = sum(
        1 for kw in set1_keywords
        if kw.lower() in query_lower
        and "연1회" + kw.lower() not in query_lower
    )
    indie_count = sum(1 for kw in independent_keywords if kw.lower() in query_lower)

    return set1_count >= 2 or (set1_count >= 1 and indie_count >= 1)


def _match_group_and_keywords(query, group_keywords, required_keywords):
    """
    group_keywords 중 1개 이상(OR)
    AND required_keywords 중 1개 이상(OR) 이어야 True.
    """
    if not _match_keywords(query, group_keywords):
        return False
    return _match_keywords(query, required_keywords)




# ============================================================
# 4. 메인 빌더 함수
# ============================================================
def build_prompt_template(query):
    """
    질문 내용을 분석해서 필요한 지식 블록만 조합한 프롬프트 반환.


    Args:
        query: 사용자 질문 (동의어 치환 후)


    Returns:
        str: 완성된 프롬프트 템플릿 문자열 ({question}, {context} 포함)
    """
    parts = [BASE_PROMPT]
    injected = []


    # 브릿지 모듈 먼저 체크
    bridge_active = _match_keywords(query, PROMPT_MODULES["브릿지"]["keywords"])
    periodontal_active = "keywords_combo" in PROMPT_MODULES.get("치주치료_산정", {}) and \
        _match_periodontal(
            query,
            PROMPT_MODULES["치주치료_산정"]["keywords_combo"]["set1"],
            PROMPT_MODULES["치주치료_산정"]["keywords_combo"]["independent"]
        )

    anesthesia_active = _match_keywords(query, PROMPT_MODULES["마취_산정"]["keywords"])
    perio_exam_active = "keywords_combo" in PROMPT_MODULES.get("치주낭측정검사_횟수산정", {}) and \
    _match_periodontal(
        query,
        PROMPT_MODULES["치주낭측정검사_횟수산정"]["keywords_combo"]["set1"],
        PROMPT_MODULES["치주낭측정검사_횟수산정"]["keywords_combo"]["independent"]
    )

    resin_active = "keywords_combo" in PROMPT_MODULES.get("보험레진_와동분류", {}) and \
        _match_periodontal(
            query,
            PROMPT_MODULES["보험레진_와동분류"]["keywords_combo"]["set1"],
            PROMPT_MODULES["보험레진_와동분류"]["keywords_combo"]["independent"]
        )

    for module_name, module_data in PROMPT_MODULES.items():
        if "group_keywords" in module_data and "required_keywords" in module_data:
            matched = _match_group_and_keywords(
                query,
                module_data["group_keywords"],
                module_data["required_keywords"]
            )
        elif "keywords_all" in module_data:
            matched = _match_keywords_all(query, module_data["keywords_all"])

        elif "keywords_combo" in module_data:                    # ← 추가
            matched = _match_periodontal(                        # ← 추가
                query,                                           # ← 추가
                module_data["keywords_combo"]["set1"],           # ← 추가
                module_data["keywords_combo"]["independent"]     # ← 추가
            )                                                    # ← 추가
        else:
            matched = _match_keywords(query, module_data["keywords"])


        if matched:
            # 특정 모듈 활성화 시 치식_위치, 치면_방향 제외
            if bridge_active and module_name in ["치식_위치", "치면_방향"]:
                continue
            if periodontal_active and module_name in ["치식_위치", "치면_방향"]:
                continue
            if anesthesia_active and module_name in ["치식_위치", "치면_방향"]:
                continue
            if perio_exam_active and module_name in ["치식_위치", "치면_방향"]:
                continue
            if resin_active and module_name in ["치식_위치", "치면_방향"]:
                continue
            parts.append(module_data["text"])
            injected.append(module_name)


    # 마지막에 질문/문서/답변 템플릿 추가
    parts.append("""
질문: {question}
문서: {context}
답변:""")


    prompt = "\n".join(parts)


    # ADR-0002 허용 수정 (ii): 디버그 print → structlog (import side-effect / stdout 오염 방지)
    if injected:
        import structlog as _structlog
        _structlog.get_logger("rag.prompt_builder").info("modules_injected", modules=injected)


    return prompt
